"use client";
import {useEffect,useRef,useState} from 'react';import {hotelClient,hotelRpc} from '@/lib/pilot';import type {HandoffScope} from '@/lib/cashier-handoff';import {CashierJournalLink} from './cashier-journal-link';import {bankCloseMoney} from '@/lib/cashier-bank-close';
type Entry={movement_id:string;kind:'cash_in'|'cash_out';amount_minor:string;reason:string;already_linked:boolean};
export function CashierCustodyLinks({scope,session,account,disabled=false,onSaved}:{scope:HandoffScope;session:string;account:string;disabled?:boolean;onSaved:()=>void}){const [entries,setEntries]=useState<Entry[]|null>(null),[next,setNext]=useState<string|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
async function load(more=false){if(lock.current||disabled)return;lock.current=true;setBusy(true);setError('');try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen cash accounting.');const before=more?next:null,r=await hotelRpc<Record<string,unknown>>('cashier_custody_journal_sources',{p_tenant:scope.tenant,p_property:scope.property,p_session:session,p_before:before});if(r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.session_id!==session||!Array.isArray(r.entries)||r.entries.length>50||typeof r.has_more!=='boolean')throw Error('Custody sources do not match this drawer.');let previous=before;const list=r.entries as Entry[];for(const e of list){if(!e||typeof e.already_linked!=='boolean'||typeof e.movement_id!=='string'||! /^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(e.movement_id)||previous!==null&&e.movement_id>=previous||!['cash_in','cash_out'].includes(e.kind)||typeof e.amount_minor!=='string'||! /^[1-9][0-9]*$/.test(e.amount_minor)||typeof e.reason!=='string'||!e.reason.trim())throw Error('Invalid custody source.');previous=e.movement_id;}if(r.has_more&&(list.length!==50||r.next_cursor!==list[49].movement_id)||!r.has_more&&r.next_cursor!==null)throw Error('Invalid custody source page.');const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen cash accounting.');if(alive.current){setEntries(list);setNext(r.has_more?r.next_cursor as string:null)}}catch(e){if(alive.current){setEntries(null);setNext(null);setError(e instanceof Error?e.message:'Unable to load custody sources.')}}finally{lock.current=false;if(alive.current)setBusy(false)}}
return <section><h4>Custody movement accounting</h4><button type="button" disabled={disabled||busy} onClick={()=>void load()}>Load custody movements</button>{error&&<p role="alert">{error}</p>}{entries&&(entries.length?<>{entries.map(e=><div key={e.movement_id}><p>{e.kind==='cash_in'?'Cash in':'Cash out'}: {bankCloseMoney(e.amount_minor)} — {e.reason}{e.already_linked?' (journal linked)':' (journal needed)'}</p><CashierJournalLink source={{scope,kind:'custody',source:e.movement_id,account}} disabled={disabled||busy} onSaved={onSaved}/></div>)}{next&&<button type="button" disabled={disabled||busy} onClick={()=>void load(true)}>Next custody page</button>}</>:<p>No custody movements on this page.</p>)}</section>}
